// Flexible search function with optional filters
export function searchTodos(options = {}) {
  const { query, done } = options;

  return listTodos().filter(todo => {
    // Filter by text query if provided
    if (query && typeof query === 'string') {
      if (!todo.text.includes(query)) {
        return false;
      }
    }

    // Filter by done status if provided
    if (done !== undefined) {
      if (todo.done !== done) {
        return false;
      }
    }

    return true;
  });
}

// Convenience wrapper for backward compatibility
export function searchTodosByStatus(query, done) {
  return searchTodos({ query, done });
}

